package in.smartcampus;
import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import java.io.*;import java.sql.*;
@WebServlet("/event-register") public class EventRegisterServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){r.sendRedirect(q.getContextPath()+"/login");return;}try(Connection c=DB.get();PreparedStatement ps=c.prepareStatement("INSERT INTO registrations(user_id,event_id) SELECT ?,id FROM events WHERE id=? AND event_date>=CURDATE() ON DUPLICATE KEY UPDATE user_id=VALUES(user_id)")){ps.setInt(1,(Integer)s.getAttribute("userId"));ps.setInt(2,Integer.parseInt(q.getParameter("eventId")));ps.executeUpdate();r.sendRedirect(q.getContextPath()+"/events?msg=Registration+saved");}catch(Exception e){throw new ServletException(e);}}}